bool IDevice_getCapabilities_ForwardToCallback::Accept(
    mojo::Message* message) {

  DCHECK(message->is_serialized());
  internal::IDevice_getCapabilities_ResponseParams_Data* params =
      reinterpret_cast<
          internal::IDevice_getCapabilities_ResponseParams_Data*>(
              message->mutable_payload());
  
  bool success = true;
  android::nn::Capabilities p_capabilities{};
  IDevice_getCapabilities_ResponseParamsDataView input_data_view(params, message);
  
  if (success && !input_data_view.ReadCapabilities(&p_capabilities))
    success = false;
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        IDevice::Name_, 0, true);
    return false;
  }
  if (!callback_.is_null())
    std::move(callback_).Run(
std::move(p_capabilities));
  return true;
}

